import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Uma borda é uma moldura ao redor de uma foto. Ela separa a imagem do que está ao redor, adiciona um toque final e dá à foto uma sensação de estar completa.</p>\n<p>As bordas fazem parte da fotografia desde o começo. Impressões eram montadas em cartão, slides eram guardados em molduras, e hoje uma borda digital faz o mesmo trabalho na tela.</p>\n<p>Este guia explica como as bordas funcionam, quais estilos escolher e como usá-las bem. Ele cobre bordas sólidas, estilos Polaroid, molduras com brilho em gradiente, sombras e escolhas de cor.</p>\n<h2 id=\"what-is-a-border\">O que É uma Borda de Imagem?</h2>\n<p>Uma borda é uma faixa de cor ou padrão adicionada ao redor das bordas de uma imagem. Ela fica fora da foto em si, então não cobre nenhuma parte da imagem.</p>\n<p>As bordas servem a dois propósitos. Elas decoram a imagem, dando um aspecto acabado, e a separam do fundo, o que ajuda a se destacar em uma página cheia.</p>\n<p>Uma borda é diferente de um corte. Cortar remove pixels das bordas, enquanto uma borda adiciona pixels ao redor, deixando a imagem final um pouco maior.</p>\n<p>Pense em uma borda como uma moldura na parede. A moldura não muda a pintura, mas muda como a pintura é vista, e uma boa moldura faz o trabalho parecer melhor.</p>\n<h2 id=\"solid-borders\">Bordas Sólidas: A Moldura Clássica</h2>\n<p>Uma borda sólida é uma única faixa de cor com largura uniforme ao redor da imagem. É o estilo mais simples, e combina com quase qualquer foto, de retratos a fotos de produto.</p>\n<p>Bordas brancas são as mais comuns. Elas dão à foto uma sensação limpa de galeria e funcionam em qualquer fundo, porque o branco separa a imagem da página.</p>\n<p>Bordas pretas passam mais drama. Combinam com fotos de clima pesado, fotos noturnas e arte, onde a moldura escura adiciona peso e foco à imagem.</p>\n<p>Bordas coloridas podem combinar com uma marca ou um tema. Uma borda pastel suave combina com uma foto de casamento, enquanto uma cor ousada combina com um cartaz ou um gráfico de promoção.</p>\n<h2 id=\"polaroid-style\">Estilo Polaroid: O Favorito Retrô</h2>\n<p>Uma borda Polaroid imita o visual do filme instantâneo: uma moldura branca com uma faixa mais grossa embaixo. Transmite nostalgia, casualidade e diversão, e é por isso que combina com fotos de férias e memórias.</p>\n<p>A faixa inferior grossa é a assinatura do estilo. Ela dá espaço para uma legenda escrita à mão, uma data ou uma nota curta, como em uma impressão Polaroid de verdade.</p>\n<p>Bordas Polaroid funcionam melhor em fotos casuais e pessoais. Elas parecem deslocadas em um retrato formal ou uma foto de produto, onde uma borda sólida limpa é mais adequada.</p>\n<p>O <a href=\"/pt/adicionar-borda-a-imagem/\">Gerador de bordas para imagem</a> inclui um estilo Polaroid como uma de suas opções de borda. Ele aplica o formato clássico automaticamente, incluindo a faixa inferior mais larga.</p>\n<h2 id=\"gradient-glow\">Molduras com Brilho em Gradiente</h2>\n<p>Uma moldura com brilho em gradiente mistura duas ou mais cores ao redor da imagem, criando uma borda suave e brilhante. Transmite modernidade e clima digital, e combina com gráficos sociais e cartazes.</p>\n<p>O brilho é calculado a partir de um ângulo e um conjunto de cores. Mudar o ângulo move a mistura ao redor da moldura, então as mesmas cores podem produzir muitos visuais diferentes.</p>\n<p>Molduras em gradiente funcionam bem em fotos escuras, onde a borda clara adiciona energia. Podem sobrecarregar uma foto clara e arejada, então use quando a imagem precisar de drama.</p>\n<p>Mantenha o brilho sutil para trabalhos profissionais. Um gradiente suave adiciona polimento, enquanto um brilho forte e vivo distrai da própria foto.</p>\n<h2 id=\"border-size\">Tamanho da Borda: De 1% a 25%</h2>\n<p>O tamanho da borda é definido como uma porcentagem da imagem, de 1 por cento a 25 por cento. Uma borda pequena é uma linha fina, enquanto uma borda grande vira uma margem larga ao redor da foto.</p>\n<p>Uma borda fina de 1 a 3 por cento combina com a maioria das fotos. Ela emoldura a imagem sem tirar a atenção dela, e funciona em qualquer tamanho de exibição.</p>\n<p>Uma borda média de 5 a 10 por cento cria uma sensação de galeria. Ela dá espaço para a foto respirar e combina com impressões, portfólios e slides de apresentação.</p>\n<p>Uma borda grande acima de 15 por cento vira uma declaração de design. Combina com cartazes e gráficos sociais, onde a moldura faz parte do visual e não é só uma borda.</p>\n<h2 id=\"frame-radius-vs-photo-radius\">Raio da Moldura ou Raio da Foto</h2>\n<p>O raio da moldura controla a curvatura da borda externa da borda, enquanto o raio da foto controla a curvatura da borda interna onde a borda encontra a foto.</p>\n<p>Definir os dois com o mesmo valor dá uma moldura arredondada uniforme. Definir de jeitos diferentes cria uma borda grossa no meio de cada lado e fina nos cantos.</p>\n<p>Para uma moldura arredondada simples, defina os dois raios com o mesmo número. O resultado é uma curva limpa e consistente que parece profissional em cartões e postagens sociais.</p>\n<p>Para um estilo Polaroid, mantenha os raios baixos. O visual clássico de filme instantâneo tem cantos quadrados, e arredondá-los demais quebra o clima retrô.</p>\n<h2 id=\"drop-shadows\">Sombras: Como Adicionar Profundidade</h2>\n<p>Uma sombra adiciona uma borda escura suave atrás da imagem emoldurada, o que faz parecer que ela flutua sobre a página. Adiciona profundidade e uma sensação de acabamento.</p>\n<p>As sombras funcionam melhor em fundos claros, onde a borda escura é visível. Em um fundo escuro, a sombra se mistura e adiciona pouco à imagem.</p>\n<p>As sombras somem quando você exporta como JPG. O formato JPG não tem transparência, então a sombra, que precisa de um fundo transparente para aparecer, não pode ser salva nesse formato.</p>\n<p>Exporte como PNG ou WebP para manter a sombra. Os dois formatos aceitam transparência, então a sombra sobrevive à exportação e aparece corretamente em qualquer fundo.</p>\n<h2 id=\"colour-choices\">Como Escolher as Cores da Borda</h2>\n<p>Branco é a cor de borda mais segura. Combina com qualquer foto, funciona em qualquer fundo e dá à imagem uma sensação limpa de galeria que nunca parece datada.</p>\n<p>Preto é a segunda mais segura. Adiciona drama e foco, e combina com fotos de clima pesado, fotos noturnas e arte, onde uma borda clara pareceria deslocada.</p>\n<p>Combine a borda com uma cor da foto para um visual desenhado. Uma borda que pega a cor de um vestido, um céu ou um produto amarra a moldura à imagem.</p>\n<p>Evite bordas claras e saturadas em fotos sérias. Uma moldura neon em um retrato de casamento parece um erro, enquanto uma moldura neutra e suave parece intencional.</p>\n<h2 id=\"quick-frame-presets\">Predefinições Rápidas de Moldura</h2>\n<p>A ferramenta inclui quatro predefinições rápidas de moldura, cada uma configurando estilo, tamanho, cor e sombra da borda em um clique. São um ponto de partida rápido para visuais comuns.</p>\n<p>As predefinições não são travadas. Depois de clicar em uma, você pode mudar qualquer configuração, incluindo a cor da moldura, o tamanho ou a sombra, para combinar com a sua foto.</p>\n<p>Use as predefinições para explorar estilos rapidamente. Clique nelas e veja qual combina com a sua imagem, depois ajuste as configurações a partir daí.</p>\n<p>Para um visual consistente em um conjunto de fotos, use a mesma predefinição para todas elas. Um lote de imagens com molduras iguais parece uma série, enquanto molduras misturadas parecem aleatórias.</p>\n<h2 id=\"borders-for-social\">Bordas para Redes Sociais</h2>\n<p>As bordas ajudam uma foto a se destacar em um feed lotado. Uma borda branca separa a imagem das postagens ao redor, e o olho é atraído para a foto emoldurada.</p>\n<p>Mantenha as bordas sociais finas. Uma borda grossa ocupa espaço em uma prévia pequena de feed, deixando menos espaço para a própria foto, que é o que as pessoas vieram ver.</p>\n<p>Use um estilo de borda consistente nas suas postagens. Uma moldura reconhecível vira parte da sua identidade visual, e os seguidores começam a identificar as suas postagens antes de ler o seu nome.</p>\n<p>Confira a imagem com borda no tamanho de feed. Uma borda que parece boa em tamanho real pode dominar uma prévia pequena, então teste antes de publicar.</p>\n<h2 id=\"borders-for-print\">Bordas para Impressão</h2>\n<p>Fotos impressas usam bordas há mais de um século, e uma borda digital prepara uma imagem para o mesmo tratamento. Uma borda branca ao redor de uma impressão dá uma sensação de galeria.</p>\n<p>Para impressões, use uma borda média de 5 a 10 por cento. O espaço extra dá respiro à impressão e oferece uma margem para manusear sem tocar a imagem.</p>\n<p>Confira o tamanho de impressão antes de adicionar uma borda. Uma borda aumenta as dimensões totais, então uma foto com borda precisa de um papel maior que a mesma foto sem borda.</p>\n<p>Para uma impressão emoldurada, a borda faz parte do design. Uma borda branca dentro de uma moldura escura cria um efeito de passe-partout, que é a apresentação clássica de galeria.</p>\n<h2 id=\"borders-for-products\">Bordas para Fotos de Produto</h2>\n<p>Fotos de produto precisam de enquadramento consistente, porque uma página de loja com bordas diferentes parece descuidada. Use o mesmo estilo e tamanho de borda para cada imagem de produto.</p>\n<p>Uma borda branca fina combina com a maioria dos produtos. Ela separa o item do fundo da página sem distrair do próprio produto.</p>\n<p>Evite bordas coloridas em fotos de produto, a menos que a cor faça parte da sua marca. Uma moldura viva pode brigar com o produto e deixar o anúncio pouco profissional.</p>\n<p>Para uma promoção, uma borda colorida pode destacar a oferta. Uma moldura vermelha ou dourada ao redor de um produto com desconto atrai o olho, que é o objetivo da promoção.</p>\n<h2 id=\"transparency-and-formats\">Transparência, Formatos e Exportação</h2>\n<p>A ferramenta mostra um xadrez cinza e branco ao redor da moldura na prévia. Esse padrão significa transparência, não um fundo cinza, e mostra onde a imagem é transparente.</p>\n<p>Exportar como PNG ou WebP preserva a transparência, incluindo cantos arredondados e sombras. Exportar como JPG achata tudo em um fundo sólido.</p>\n<p>Para uma imagem emoldurada com cantos arredondados, escolha PNG ou WebP. Uma exportação JPG preenche os cantos transparentes com uma cor sólida, o que quebra o visual arredondado.</p>\n<p>O controle de qualidade aparece para exportações JPG e WebP e some para PNG, porque PNG não tem perda e não tem configuração de qualidade para ajustar.</p>\n<h2 id=\"borders-vs-frames-vs-matting\">Bordas, Molduras e Passe-partout: Qual É a Diferença?</h2>\n<p>Uma borda é uma faixa de cor ao redor da imagem, adicionada digitalmente. Uma moldura é um objeto físico que segura uma impressão, e o passe-partout é o cartão dentro da moldura que envolve a impressão.</p>\n<p>Bordas digitais imitam o passe-partout. Uma borda branca larga ao redor de uma foto parece uma impressão com passe-partout, e é por isso que parece em casa em um contexto de galeria.</p>\n<p>Uma borda fina é mais próxima da borda de uma moldura. Ela define o limite da imagem sem adicionar o espaço generoso que o passe-partout oferece.</p>\n<p>Escolha conforme a sensação que você quer. O passe-partout transmite formalidade e clima de galeria, enquanto uma moldura fina transmite modernidade e limpeza.</p>\n<h2 id=\"privacy-local-processing\">Privacidade: Como Emoldurar sem Enviar</h2>\n<p>Todo trabalho de borda acontece no seu navegador. Suas fotos nunca são enviadas para um servidor, o que importa quando as imagens são pessoais, trabalhos de cliente ou produtos não lançados.</p>\n<p>Essa é uma vantagem real sobre editores na nuvem. Uma foto de produto ou um retrato de família não deveria viajar para um servidor que você não conhece, só para adicionar uma moldura.</p>\n<p>A ferramenta também remove os dados de GPS do EXIF na exportação. Uma foto emoldurada baixada pela ferramenta não carrega nenhum registro de onde foi tirada.</p>\n<p>Guarde a foto original sem borda. Depois que uma borda é achatada em uma exportação, ela não pode ser removida daquele arquivo, então a original é a sua única cópia limpa.</p>\n<h2 id=\"common-border-mistakes\">Erros Comuns com Bordas</h2>\n<p>O erro mais comum é uma borda grossa demais. Uma moldura pesada sobrecarrega uma foto pequena e deixa pouco espaço para a própria imagem, que é o que as pessoas vieram ver.</p>\n<p>Outro erro é uma cor que briga com a foto. Uma borda viva em uma imagem suave e apagada disputa a atenção com a foto e deixa todo o design errado.</p>\n<p>Muita gente também esquece que uma borda aumenta o tamanho total. Uma foto com uma borda de 25 por cento é bem maior que a original, e pode não caber mais no destino.</p>\n<p>Por fim, não use uma sombra com exportação JPG e espere que ela sobreviva. JPG não tem transparência, então a sombra some e o resultado parece plano.</p>\n<p>Para o processo passo a passo, veja <a href=\"/pt/blog/como-colocar-borda-em-uma-foto/\">Como colocar borda em uma foto</a>. Para ideias de estilo, leia <a href=\"/pt/blog/moldura-para-foto-estilos/\">Moldura para foto: estilos para Instagram, impressão e produto</a>, e para arredondar os cantos de uma foto emoldurada, experimente a <a href=\"/pt/arredondar-cantos-da-imagem/\">ferramenta Arredondar cantos da imagem</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Qual é a melhor cor de borda para uma foto?","answer":"Branco é a escolha mais segura: combina com qualquer foto, funciona em qualquer fundo e dá uma sensação limpa de galeria. Preto adiciona drama para fotos de clima pesado ou noturnas. Combine a borda com uma cor da foto para um visual desenhado, e evite cores vivas em imagens sérias."},{"question":"Adicionar uma borda muda o tamanho da minha imagem?","answer":"Sim. Uma borda adiciona pixels ao redor da foto, então a imagem final é maior que a original. Uma borda de 10 por cento em cada lado adiciona 20 por cento à largura e à altura. Confira as dimensões finais antes de enviar para uma plataforma com limites de tamanho."},{"question":"Por que a minha sombra sumiu depois de exportar como JPG?","answer":"JPG não tem transparência, e uma sombra precisa de um fundo transparente para aparecer. Exporte como PNG ou WebP, que aceitam transparência e mantêm a sombra. O xadrez da prévia mostra onde a imagem é transparente."},{"question":"Qual é a diferença entre uma borda Polaroid e uma borda sólida?","answer":"Uma borda Polaroid tem uma faixa mais grossa embaixo, imitando filme instantâneo, com espaço para uma legenda. Uma borda sólida é uma faixa uniforme de uma cor nos quatro lados. Polaroid combina com fotos casuais, enquanto bordas sólidas combinam com quase tudo."},{"question":"Dá para adicionar uma borda a uma foto no celular?","answer":"Sim. O gerador de bordas funciona no navegador do celular: envie da galeria, escolha um estilo e um tamanho, visualize a moldura e baixe o resultado. As predefinições rápidas facilitam emoldurar uma foto em segundos em uma tela pequena."},{"question":"Fotos de produto devem ter bordas?","answer":"Uma borda branca fina geralmente ajuda, já que separa o produto da página e deixa os anúncios organizados. Mantenha o estilo idêntico em todo o catálogo. Evite bordas coloridas, a menos que a cor faça parte da sua marca."}];
